def _percentual(variavel, padrao):
    """Lê uma fração (0.30) da configuração antiga e devolve em % (30.00)."""
    try:
        return (Decimal(os.environ.get(variavel) or padrao) * 100).quantize(Decimal('0.01'))
    except InvalidOperation:
        return (Decimal(padrao) * 100).quantize(Decimal('0.01'))


def converter_mecanico_unico(apps, schema_editor):
    """Bancos da versão com um mecânico só: cria esse mecânico e liga os serviços antigos a ele.

    O nome e as partilhas vêm das variáveis antigas OFICINA_NOME_MECANICO, OFICINA_PARTE_DONO_MECANICO e
    OFICINA_PARTE_DONO_AMBOS, se ainda estiverem no ambiente (senão valem os padrões antigos). Depois disso
    a conta é do cadastro de mecânicos; para corrigir o nome ou os percentuais, use /painel/ → Mecânicos.
    Cada serviço recebe o percentual que valia para ele, então o faturamento passado não muda.
    """
    ItemOS = apps.get_model('core', 'ItemOS')
    Mecanico = apps.get_model('core', 'Mecanico')
    antigos = ItemOS.objects.filter(executor__in=['mecanico', 'ambos'])
    if not antigos.exists():
        return
    sozinho = _percentual('OFICINA_PARTE_DONO_MECANICO', '0.30')
    junto = _percentual('OFICINA_PARTE_DONO_AMBOS', '0.50')
    mecanico = Mecanico.objects.create(nome=os.environ.get('OFICINA_NOME_MECANICO') or 'Mecânico',
                                       percentual_dono_sozinho=sozinho, percentual_dono_junto=junto)
    antigos.filter(executor='mecanico').update(mecanico=mecanico, percentual_dono=sozinho)
    antigos.filter(executor='ambos').update(mecanico=mecanico, percentual_dono=junto)


